			m_roll -= 6.2831855f;

		m_pitch += spin;

		if (m_pitch > 6.2831855f)
			m_pitch -= 6.2831855f;

		m_heading += spin;

		if (m_heading > 6.2831855f)
			m_heading -= 6.2831855f;

